insert into public.landmarks (id, name, category, region, description, lat, lng, elevation_m, area_km2, image, image_credit, sort_order, details)
values
  ('halti', 'Halti', 'peak', 'Enontekiö, Lapland', 'Finland''s highest point sits on a shoulder of Halti fell, right on the Norwegian border in the far northwest. Reaching it is a multi-day trek across open, treeless Käsivarsi wilderness, usually from Kilpisjärvi along the Nordkalott Trail. The summit cairn rewards the effort with views over Norway''s higher peaks.', 69.3081, 21.2633, 1324, null, '', null, 0, '{"difficulty":5,"hike":{"name":"Haltin vaellusreitti","trailhead":"Kilpisjärvi","distance":"104 km","duration":"7 days","elevationGainM":580},"protectedArea":"Käsivarsi Wilderness Area"}'::jsonb),
  ('saana', 'Saana', 'peak', 'Enontekiö, Lapland', 'Saana''s flat-topped, steep-sided silhouette towers over Kilpisjärvi village and lake, making it one of Finland''s most recognisable fells. The fell is protected as part of the Saana Nature Reserve. On a clear day the views from the top reach into Sweden and Norway.', 69.0436, 20.8561, 1029, null, '', null, 1, '{"relief":{"label":"Height above Lake Kilpisjärvi","metres":556},"difficulty":3.5,"hike":{"name":"Saanan huiputus","trailhead":"Malla and Saana parking area, Kilpisjärvi","distance":"8.6 km","duration":"4 h","elevationGainM":550},"protectedArea":"Saana Nature Reserve"}'::jsonb),
  ('ukko-koli', 'Ukko-Koli', 'peak', 'Lieksa, North Karelia', 'Ukko-Koli is the highest of the Koli hills, rising about 250 metres above Lake Pielinen. Its view of islands scattered across the lake inspired Finnish painters and composers in the 1890s and became a symbol of Finnish national landscape. A short path leads from the Koli visitor centre to the summit rocks.', 63.0944, 29.8086, 347, null, '', null, 2, '{"relief":{"label":"Prominence","metres":253},"difficulty":1,"hike":{"name":"Huippujen kierros","trailhead":"Koli Nature Centre Ukko","distance":"1.4 km","duration":"30 min"},"protectedArea":"Koli National Park"}'::jsonb),
  ('taivaskero', 'Taivaskero', 'peak', 'Muonio, Lapland', 'Taivaskero is the highest summit of the Pallastunturi fells and of the whole Pallas-Yllästunturi National Park. A popular loop trail starts at the Pallastunturi visitor centre and crosses bare, rocky fell tops. In 1952 a flame for the Helsinki Olympic torch relay was lit on its summit by the midnight sun.', 68.074833, 24.053361, 809, null, '', null, 3, '{"relief":{"label":"Prominence","metres":509},"difficulty":3,"hike":{"name":"Taivaskeron kierros","trailhead":"Pallastunturi Visitor Centre","distance":"8.2 km","duration":"3.5 h","elevationGainM":350},"protectedArea":"Pallas-Yllästunturi National Park"}'::jsonb),
  ('sokosti', 'Sokosti', 'peak', 'Sodankylä, Lapland', 'Sokosti is the highest fell in Urho Kekkonen National Park and in eastern Lapland. It rises from the remote heart of the park, a few kilometres east of Lake Luirojärvi, and is usually climbed as part of a multi-day wilderness trek. From the bouldery summit the Saariselkä fells roll away in every direction.', 68.219, 28.1376, 718, null, '', null, 4, '{"difficulty":4.5,"hike":{"name":"Luirojärven kierros + Sokostin huiputus","trailhead":"Kiilopää","distance":"71 km + 12 km","duration":"5 days","elevationGainM":430},"protectedArea":"Urho Kekkonen National Park"}'::jsonb),
  ('kiilopaa', 'Kiilopää', 'peak', 'Sodankylä, Lapland', 'Kiilopää is one of the best-known fells of the Saariselkä area, a rounded, bare-topped summit right next to the Kiilopää fell centre. A well-marked trail climbs to the top in about two kilometres, with long sections of steps. From the summit the wilderness of Urho Kekkonen National Park stretches as far as the eye can see.', 68.341703, 27.503431, 546, null, '', null, 5, '{"difficulty":2.5,"hike":{"name":"Kiirunapolku","trailhead":"Kiilopää fell centre","distance":"5.7 km","duration":"2.5 h","elevationGainM":210},"protectedArea":"Urho Kekkonen National Park"}'::jsonb),
  ('riisitunturi', 'Riisitunturi', 'peak', 'Posio, Lapland', 'Riisitunturi is a twin-topped fell and the highest point of Riisitunturi National Park in Posio. In winter its spruces disappear under thick crown snow, turning the slopes into a landscape of frozen white figures. A short loop trail from the car park climbs to the open summit.', 66.223, 28.5591, 465, null, '', null, 6, '{"difficulty":1.5,"hike":{"name":"Riisin rääpäsy","trailhead":"Riisitunturi car park","distance":"4.5 km","duration":"2 h","elevationGainM":120},"protectedArea":"Riisitunturi National Park"}'::jsonb),
  ('noitatunturi', 'Noitatunturi', 'peak', 'Pelkosenniemi, Lapland', 'Noitatunturi, the ''witch fell'', is the highest top of the Pyhätunturi fell chain and of Pyhä-Luosto National Park. The final climb is steep and rocky. From the summit the view opens over the forests and wide aapa mires of southern Lapland.', 67.0138, 27.1483, 540, null, '', null, 7, '{"relief":{"label":"Prominence","metres":339},"difficulty":3.5,"hike":{"name":"Noitatunturin valloitus","trailhead":"Pyhä Nature Centre Naava","distance":"12.5 km","duration":"5 h","elevationGainM":340},"protectedArea":"Pyhä-Luosto National Park"}'::jsonb),
  ('sarkitunturi', 'Särkitunturi', 'peak', 'Muonio, Lapland', 'Särkitunturi is a compact fell in Muonio, just outside Pallas-Yllästunturi National Park, with its trailhead right by road 79 between Muonio and Levi. A short, signposted trail leads past a campfire shelter to the summit. It is one of the quickest ways to reach open fell-top views in western Lapland.', 67.867643, 23.94985, 492, null, '', null, 8, '{"difficulty":2.5,"hike":{"name":"Särkitunturin saavutus","trailhead":"Särkitunturi parking area, road 79","distance":"6.4 km","duration":"3 h","elevationGainM":190}}'::jsonb),
  ('kumputunturi', 'Kumputunturi', 'peak', 'Kittilä, Lapland', 'Kumputunturi is a solitary fell in Kittilä with a steep northern face and a gentler southern slope. The fell and its surroundings are a Natura 2000 site, and Metsähallitus lists it as a historical site. There are no facilities on the open summit, and fog or storms can roll in within hours.', 67.722, 25.5612, 581, null, '', null, 9, '{"difficulty":3,"hike":{"name":"Kumputunturin reitti","trailhead":"Kittilä–Sodankylä road (road 80), then a gravel road","distance":"8.4 km","duration":"3.5 h","elevationGainM":320},"protectedArea":"Natura 2000 site"}'::jsonb),
  ('muotkatunturi', 'Muotkatunturi', 'wilderness-area', 'Inari, Lapland', 'Muotkatunturi stretches from a rolling, treeless fell plateau cut by river valleys in the north to mountain birch woods, bogs and old pine forests in the south. Lake Peltojärvi is its largest lake, fed by countless rivers and brooks. There are no marked trails, so visitors plan their own routes.', 69.151889, 26.306, null, 1570, '', null, 10, '{"rank":1,"wildernessScore":5,"wildlife":["Reindeer","Golden eagle","Willow grouse","Mountain hare"],"reindeer":"Likely","reindeerBasis":"Part of the Muotkatunturi and Paistunturi herding districts, with about 2 to 2.6 reindeer per km²."}'::jsonb),
  ('kaldoaivi', 'Kaldoaivi', 'wilderness-area', 'Utsjoki, Lapland', 'Kaldoaivi is Finland''s largest wilderness area, a roadless expanse of fells that continues across the border into Norway. Its landscape ranges from deep, steep-sided river valleys to gentle fell slopes, and it is one of Finland''s most important breeding grounds for arctic waders. The only marked route, the Sevettijärvi–Pulmanki trail, crosses it from south to north.', 69.69125, 27.867861, null, 2924, '', null, 11, '{"rank":2,"wildernessScore":5,"wildlife":["Golden plover","Gyrfalcon","Snowy owl","Bar-tailed godwit","Otter","Reindeer"],"reindeer":"Very likely","reindeerBasis":"About 10,000 reindeer graze here, and herding is a main livelihood."}'::jsonb),
  ('paistunturi', 'Paistunturi', 'wilderness-area', 'Utsjoki, Lapland', 'Paistunturi is a land of fell heaths, mountain birch forest and aapa and palsa mires, split in two by the Kevo Strict Nature Reserve. Rolling highlands and deep river valleys fill its middle and north, where Gáimmoivi, its highest fell, looks out toward Norway''s snowy peaks. Old nesting mounds recall the Arctic fox, which last bred here in 1996.', 69.594333, 26.713389, null, 1570, '', null, 12, '{"rank":3,"wildernessScore":4,"wildlife":["Reindeer","Lemmings","Voles"],"reindeer":"Very likely","reindeerBasis":"Almost half of the Paistunturi herding district''s land lies inside the area."}'::jsonb),
  ('hammastunturi', 'Hammastunturi', 'wilderness-area', 'Inari, Lapland', 'Hammastunturi lies between Urho Kekkonen and Lemmenjoki national parks. Pine forests and low fells grow on nutrient-poor granulite bedrock, and the Ivalojoki river winds through the area. Its gold-rush past lives on at Kultala, where hundreds of prospectors once lived.', 68.571583, 26.683083, null, 1825, '', null, 13, '{"rank":4,"wildernessScore":4,"wildlife":["Golden eagle","Siberian jay","Siberian tit","Northern hawk owl","Willow grouse","Otter"],"reindeer":"Very likely","reindeerBasis":"Reindeer use it all year round, with summer, winter, calving and rutting pastures."}'::jsonb),
  ('vatsari', 'Vätsäri', 'wilderness-area', 'Inari, Lapland', 'Vätsäri runs from the north-eastern shore of Lake Inari to the Norwegian border, a maze of thousands of small lakes, rocky ground and Scots pine taiga. The rocky bays of Lake Inari reach deep into its backwoods. The difficult terrain makes it one of Lapland''s most demanding hiking destinations.', 69.340778, 28.831944, null, 1550, '', null, 14, '{"rank":5,"wildernessScore":4,"wildlife":["Brown bear","Pine marten","Red fox","Stoat","Spotted redshank"],"reindeer":"Likely","reindeerBasis":"Shared by four herding districts, with about 2 reindeer per km²."}'::jsonb),
  ('poyrisjarvi', 'Pöyrisjärvi', 'wilderness-area', 'Enontekiö, Lapland', 'Pöyrisjärvi is known for its sand dunes and long sandy ridges, most of them on the north side of Lake Pöyrisjärvi. Small lakes with sandy shores dot the area, dry pine forest gives way to birch further north, and the Pöyrisvuoma mire is one of Finland''s most valuable palsa bogs. Late summer and early autumn are the most popular times to visit.', 68.583722, 24.133972, null, 1280, '', null, 15, '{"rank":6,"wildernessScore":4,"wildlife":["Brown bear","Wolverine","Lynx","Wading birds","Waterfowl"],"reindeer":"Very likely","reindeerBasis":"The Näkkälä herding district''s summer pasture."}'::jsonb),
  ('kasivarsi', 'Käsivarsi', 'wilderness-area', 'Enontekiö, Lapland', 'Käsivarsi, in Finland''s north-western ''arm'', lies mostly above the treeline and holds all but one of the country''s fells over 1,000 metres. The average yearly temperature stays below freezing and the growing season lasts only about a hundred days. Its rocky plateau is home to rare plants and animals found nowhere else in Finland.', 68.977278, 21.587333, null, 2206, '', null, 16, '{"rank":7,"wildernessScore":3,"wildlife":["Arctic fox","Wolverine","Lynx","Snowy owl","Peregrine falcon","Reindeer"],"reindeer":"Likely","reindeerBasis":"Lies entirely within the Käsivarsi herding district, with about 2 reindeer per km²."}'::jsonb),
  ('tarvantovaara', 'Tarvantovaara', 'wilderness-area', 'Enontekiö, Lapland', 'Tarvantovaara is a landscape of free-flowing rivers, wetlands and low fells, bordered to the north-west by the Lätäseno-Hietajoki mire reserve. The Tarvantojoki river through its centre is gentle enough for beginner canoeists. Nature writer Yrjö Kokko found his first whooper swan nests here, work that helped save the species in Finland.', 68.568639, 22.91625, null, 670, '', null, 17, '{"rank":8,"wildernessScore":3,"wildlife":["Whooper swan","Willow grouse","Mountain hare","Waterfowl"],"reindeer":"Very likely","reindeerBasis":"5,000 to 7,000 reindeer graze here: about 40% of the Käsivarsi district''s pasture."}'::jsonb),
  ('pulju', 'Pulju', 'wilderness-area', 'Enontekiö, Lapland', 'Pulju is a land of large mires and rounded hills and fells, with spruce on the southern hills giving way to pine and fell birch in the north. Road 956 runs through its centre, making it one of the easiest wilderness areas to reach. In late summer its mires draw cloudberry pickers.', 68.342333, 24.915361, null, 614, '', null, 18, '{"rank":9,"wildernessScore":3,"wildlife":["Willow grouse","Mountain hare","Capercaillie","Black grouse","Stoat"],"reindeer":"Likely","reindeerBasis":"Shared by three herding districts, with about 1.7 to 2.3 reindeer per km²."}'::jsonb),
  ('kemihaara', 'Kemihaara', 'wilderness-area', 'Savukoski, Lapland', 'Kemihaara borders Urho Kekkonen National Park to the north and the Kemijoki river to the east. Pine backwoods, spruce-filled ravines and rocky fells over 420 metres high meet wide aapa mires that feed the headwaters of the Kemijoki and Pihtijoki rivers. Its mires are an important breeding ground for wading birds.', 67.963734, 28.710301, null, 302, '', null, 19, '{"rank":10,"wildernessScore":2,"wildlife":["Wading birds","Willow grouse","Reindeer"],"reindeer":"Very likely","reindeerBasis":"An important summer pasture on the reindeer''s route to their calving grounds."}'::jsonb),
  ('tuntsa', 'Tuntsa', 'wilderness-area', 'Savukoski, Lapland', 'Tuntsa lies where the northern limit of spruce forest crosses eastern Lapland. In 1960 it was hit by Finland''s largest recorded forest fire, and much of the burnt land is still open today, visible from the UKK hiking trail. Its bogs yield rich cloudberry crops and its slopes are covered in blueberry and lingonberry.', 67.646583, 29.52725, null, 212, '', null, 20, '{"rank":11,"wildernessScore":2,"wildlife":["Boreal forest birds"],"reindeer":"Likely","reindeerBasis":"Part of the Pohjois-Salla herding district, with about 2 reindeer per km², though a 1960 forest fire destroyed much of its pasture.","notes":{"wildlife":"BirdLife says 13 of Europe''s 15 boreal-forest bird species breed in the wider Värriö–Tuntsa area, but names no animals for Tuntsa itself."}}'::jsonb),
  ('tsarmitunturi', 'Tsarmitunturi', 'wilderness-area', 'Inari, Lapland', 'Tsarmitunturi lies in south-eastern Inari on the Russian border, between the roads to Nellim and Raja-Jooseppi. Spruce and pine forests cover the Tsarmitunturi highland and Akalauttapää, separated by the deep Pahakuru gorge. It protects Finland''s northernmost continuous spruce forest untouched by people.', 68.679972, 28.389028, null, 150, '', null, 21, '{"rank":12,"wildernessScore":2,"wildlife":["Brown bear","Moose","Reindeer","Red fox","Capercaillie","Willow grouse"],"reindeer":"Likely","reindeerBasis":"Part of the Ivalo herding district, with about 2 reindeer per km²."}'::jsonb),
  ('etela-konnevesi', 'Etelä-Konnevesi', 'national-park', 'Keski-Suomi', 'Rocky, forested hills rise straight out of the clear waters of Lake Konnevesi. Its trails climb to sweeping lake views and pass through groves of giant aspens.', 62.583333, 26.665778, null, 15.44, '', null, 22, '{"established":2014,"nature":["Lake Scenery"],"trail":{"name":"Kolmen vuoren vaellus (Three Hills hike)","distance":"14 km","duration":"6–12 h"}}'::jsonb),
  ('helvetinjarvi', 'Helvetinjärvi', 'national-park', 'Pirkanmaa', 'A rugged forest park of steep rocky hills, narrow lakes and deep gorges cut along fault lines in the bedrock. It is best known for Helvetinkolu, a steep, narrow cleft in the rock.', 62.023139, 23.852194, null, 49.8, '', null, 23, '{"established":1982,"nature":["Forest","Lake Scenery"],"trail":{"name":"Helvetistä itään nature trail","distance":"4 km"},"notes":{"trail":"No official duration found. The Haukanhieta–Helvetinkolu section has been reported closed due to flooding."}}'::jsonb),
  ('hiidenportti', 'Hiidenportti', 'national-park', 'Kainuu', 'Old spruce forests, small mires and ponds fill this backwoods park in Kainuu. Its centrepiece is the Hiidenportti gorge, where sheer cliff walls drop up to 20 metres.', 63.872528, 29.05225, null, 45, '', null, 24, '{"established":1982,"nature":["Forest"],"trail":{"name":"Hiidenkierros","distance":"3–5 km","duration":"2–4 h"}}'::jsonb),
  ('hossa', 'Hossa', 'national-park', 'Kainuu', 'Clear lakes, rivers and pine-clad eskers make up this park on the edge of the Kainuu backwoods. Its best-known sights are the Värikallio rock paintings and the Julma-Ölkky canyon lake.', 65.475111, 29.321694, null, 11, '', null, 25, '{"established":2017,"nature":["Lake Scenery"],"trail":{"name":"Värikallion kaarros","distance":"8 km","duration":"3–4 h"}}'::jsonb),
  ('isojarvi', 'Isojärvi', 'national-park', 'Keski-Suomi', 'Rugged forested hills and lakes whose woods still tell the story of a century of logging. The oldest trees grow in the Latokuusikko old-growth forest, and today the only loggers at work are beavers.', 61.700701, 25.003797, null, 19, '', null, 26, '{"established":1982,"nature":["Forest"],"trail":{"name":"Savottapolku (Logging Trail)","distance":"10 km","duration":"3–5 h"}}'::jsonb),
  ('itainen-suomenlahti', 'Itäinen Suomenlahti', 'national-park', 'Kymenlaakso', 'Rocky outer islands and skerries scattered across the eastern Gulf of Finland. On Ulko-Tammio, a nature trail and a wartime history trail cross the island.', 60.323333, 27.069222, null, 6.7, '', null, 27, '{"established":1982,"nature":["Archipelago"],"trail":{"name":"Ulko-Tammio nature trail","distance":"2.8 km","duration":"1–2 h"}}'::jsonb),
  ('kauhaneva-pohjankangas', 'Kauhaneva–Pohjankangas', 'national-park', 'Etelä-Pohjanmaa', 'Here the vast Kauhaneva raised bog meets the sandy ridge of the Pohjankangas esker. Duckboard trails lead out to bog pools and a viewing tower.', 62.183083, 22.427306, null, 57, '', null, 28, '{"established":1982,"nature":["Mire"],"trail":{"name":"Kauhalammin kierros","distance":"2.7 km","duration":"2 h"}}'::jsonb),
  ('koli-national-park', 'Koli', 'national-park', 'Pohjois-Karjala', 'Ancient quartzite hills rise above Lake Pielinen, mixing old forests, slash-and-burn meadows and lake shores. The island-dotted view from Ukko-Koli became a symbol of the Finnish national landscape.', 63.059639, 29.874278, null, 30, '', null, 29, '{"established":1991,"nature":["Forest","Lake Scenery"],"trail":{"name":"Herajärven kierros","distance":"about 61 km","duration":"3–4 days"}}'::jsonb),
  ('kolovesi', 'Kolovesi', 'national-park', 'Etelä-Savo', 'Steep rocky shores, narrow straits and forested islands on Lake Saimaa, best explored by canoe. Rock paintings around 5,000 years old decorate the cliffs of Ukonvuori.', 62.252861, 28.821944, null, 23, '', null, 30, '{"established":1990,"nature":["Lake Scenery"],"trail":{"name":"Mäntysalo trail","distance":"3.8 km","duration":"about 2 h"},"notes":{"trail":"The trail can only be reached by water."}}'::jsonb),
  ('kurjenrahka', 'Kurjenrahka', 'national-park', 'Varsinais-Suomi', 'Open bogs and forested islands of higher ground make up this mire park north of Turku. At its heart stands the Kuhankuono boundary mark, reached by a short boardwalk.', 60.731389, 22.394306, null, 29, '', null, 31, '{"established":1998,"nature":["Mire"],"trail":{"name":"Savojärvi trail","distance":"6 km","duration":"2.5 h"}}'::jsonb),
  ('lauhanvuori', 'Lauhanvuori', 'national-park', 'Etelä-Pohjanmaa', 'A broad forested hill rises about 100 metres above the surrounding plains, its top reaching around 231 metres above sea level. Its slopes are scattered with vast stone fields, the largest of them Kivijata.', 62.149139, 22.162556, null, 53, '', null, 32, '{"established":1982,"nature":["Forest","Mire"],"trail":{"name":"Pirunkierros","distance":"4.5 km","duration":"2 h"}}'::jsonb),
  ('leivonmaki', 'Leivonmäki', 'national-park', 'Keski-Suomi', 'Eskers, mires and clear lakes shaped by the Ice Age meet in this compact park. Its geology trail passes kettle holes, erratic boulders and esker ridges.', 61.922444, 26.023083, null, 29, '', null, 33, '{"established":2003,"nature":["Forest","Mire","Lake Scenery"],"trail":{"name":"Luupään lenkki","distance":"2.1 km","duration":"1 h"}}'::jsonb),
  ('lemmenjoki', 'Lemmenjoki', 'national-park', 'Lapland', 'Finland''s largest national park is a roadless expanse of fells, pine forests and river valleys. Gold prospectors still pan its streams, and the Gold Trail leads through the old prospecting grounds.', 68.637389, 25.598222, null, 2850, '', null, 34, '{"established":1956,"nature":["Fell","Forest"],"trail":{"name":"Lemmenjoki Gold Trail","distance":"25.5 km","duration":"2–3 days"}}'::jsonb),
  ('liesjarvi', 'Liesjärvi', 'national-park', 'Kanta-Häme', 'Old spruce and pine forests surround clear lakes, crossed by the narrow, pine-topped Kyynäränharju esker. The Korteniemi heritage farm keeps traditional farming alive.', 60.671028, 23.885417, null, 22, '', null, 35, '{"established":1956,"nature":["Forest","Lake Scenery"],"trail":{"name":"Pohjantikan kierros","distance":"5 km"},"notes":{"trail":"No official duration found."}}'::jsonb),
  ('linnansaari', 'Linnansaari', 'national-park', 'Etelä-Savo', 'Rocky islands and forested shores in Lake Haukivesi, part of the Saimaa lake system, reached by boat. It is home to the endangered Saimaa ringed seal, one of the world''s rarest seals.', 62.098639, 28.502417, null, 38, '', null, 36, '{"established":1956,"nature":["Lake Scenery"],"trail":{"name":"Linnavuori trail","distance":"6.5 km","duration":"3–4 h"}}'::jsonb),
  ('nuuksio', 'Nuuksio', 'national-park', 'Uusimaa', 'Rocky hills, small lakes and spruce valleys less than an hour from central Helsinki. The Siberian flying squirrel is the park''s emblem.', 60.314361, 24.527417, null, 45, '', null, 37, '{"established":1994,"nature":["Forest"],"trail":{"name":"Haukankierros","distance":"3.9 km","duration":"1.5–2 h"}}'::jsonb),
  ('oulanka', 'Oulanka', 'national-park', 'Pohjois-Pohjanmaa', 'Fast rivers, roaring rapids, sandy riverbanks and suspension bridges wind through old forest. It is famous for the Karhunkierros, one of Finland''s most popular long-distance trails.', 66.376083, 29.318972, null, 270, '', null, 38, '{"established":1956,"nature":["Rivers and Rapids"],"trail":{"name":"Karhunkierros","distance":"about 80 km","duration":"4–6 days"}}'::jsonb),
  ('pallas-yllastunturi', 'Pallas-Yllästunturi', 'national-park', 'Lapland', 'A chain of bare fells rises above the forests of western Lapland. The Hetta–Pallas trail across its fell tops, first marked in 1934, is one of Finland''s classic hikes.', 67.966222, 24.133056, null, 1020, '', null, 39, '{"established":2005,"nature":["Fell"],"trail":{"name":"Hetta–Pallas hiking trail","distance":"47.7 km","duration":"3 days"}}'::jsonb),
  ('patvinsuo', 'Patvinsuo', 'national-park', 'Pohjois-Karjala', 'Wide open bogs and old forests surround Lake Suomunjärvi. Sandy lake shores and long duckboard trails make it an easy wilderness escape.', 63.109722, 30.696583, null, 105, '', null, 40, '{"established":1982,"nature":["Mire"],"trail":{"name":"Suomunkierto","distance":"15.9 km","duration":"4–8 h"}}'::jsonb),
  ('perameri', 'Perämeri', 'national-park', 'Lapland', 'A sea park in the Kemi outer archipelago, almost entirely open water dotted with low islands. On Selkä-Sarvi, a short trail leads to an old fishing base.', 65.628944, 24.318917, null, null, '', null, 41, '{"established":1991,"nature":["Archipelago"],"trail":{"name":"Selkä-Sarvi nature trail","distance":"1 km","duration":"0.5–1 h"}}'::jsonb),
  ('petkeljarvi', 'Petkeljärvi', 'national-park', 'Pohjois-Karjala', 'Narrow eskers wind between clear lakes in this small park near the eastern border. Its esker trail is a compact introduction to the North Karelian landscape.', 62.584083, 31.1785, null, 6, '', null, 42, '{"established":1956,"nature":["Forest","Lake Scenery"],"trail":{"name":"Harjupolku (Esker Trail)","distance":"3.5 km","duration":"1–2 h"},"notes":{"trail":"Official figures. A newer local listing gives 2.5 km and about 45 minutes."}}'::jsonb),
  ('puurijarvi-isosuo', 'Puurijärvi–Isosuo', 'national-park', 'Satakunta', 'Puurijärvi, a shallow lake rich in birds, sits beside the Isosuo raised bog. An 18-metre tower at Kärjenkallio looks out over the lake.', 61.243889, 22.565, null, 27, '', null, 43, '{"established":1993,"nature":["Mire","Lake Scenery"],"trail":{"name":"Kärjenkallio bird lake trail","distance":"0.8 km there and back"},"notes":{"trail":"No duration listed; it is a short walk to the bird tower."}}'::jsonb),
  ('pyha-hakki', 'Pyhä-Häkki', 'national-park', 'Keski-Suomi', 'One of southern Finland''s finest old-growth forests, where some pines are over 400 years old. Its landmark, the Big Old Tree, stands just off the Kotajärvi trail.', 62.844528, 25.4685, null, 13, '', null, 44, '{"established":1956,"nature":["Forest"],"trail":{"name":"Kotajärven polku","distance":"6.8 km","duration":"2–3 h"}}'::jsonb),
  ('pyha-luosto', 'Pyhä-Luosto', 'national-park', 'Lapland', 'Two chains of ancient fells linked by old-growth forest and wide aapa mires. Deep gorges such as Isokuru cut through the fells, and amethyst is still mined on Lampivaara.', 67.069389, 26.977889, null, 142, '', null, 45, '{"established":2005,"nature":["Fell"],"trail":{"name":"Pyhä–Luosto hiking trail","distance":"about 30 km","duration":"2–3 days"},"notes":{"trail":"Luontoon.fi lists 47.6 km, including the extension to Yli-Luosto."}}'::jsonb),
  ('repovesi', 'Repovesi', 'national-park', 'Kymenlaakso', 'Sheer cliffs, clear lakes and pine-topped ridges in a former logging area. It is known for the hand-pulled Ketunlossi raft ferry and the Lapinsalmi suspension bridge.', 61.1885, 26.902722, null, 15, '', null, 46, '{"established":2003,"nature":["Forest","Lake Scenery"],"trail":{"name":"Ketunlenkki","distance":"3.6 km","duration":"1–2 h"},"notes":{"trail":"The Lapinsalmi suspension bridge has been closed since January 2024."}}'::jsonb),
  ('riisitunturi-national-park', 'Riisitunturi', 'national-park', 'Lapland', 'Rounded fells in Posio, famous for crown snow that turns the spruces into frozen white figures each winter. Its slopes are also known for rare hillside mires.', 66.226278, 28.486806, null, 77, '', null, 47, '{"established":1982,"nature":["Fell"],"trail":{"name":"Riisin rääpäsy","distance":"4.5 km","duration":"2–3 h"}}'::jsonb),
  ('rokua', 'Rokua', 'national-park', 'Pohjois-Pohjanmaa', 'Pine heaths on a huge esker, with inland dunes, kettle-hole lakes and white carpets of lichen. It is part of Rokua Geopark, Finland''s first UNESCO Global Geopark.', 64.573861, 26.469611, null, 4.3, '', null, 48, '{"established":1956,"nature":["Forest"],"trail":{"name":"Syvyydenkierros","distance":"6.3 km","duration":"2–3 h"}}'::jsonb),
  ('archipelago', 'Saaristomeri', 'national-park', 'Varsinais-Suomi', 'More than 2,000 islands and skerries in the outer Archipelago Sea, most of the park open water. Traditional farming keeps meadows open on the larger islands, with a nature centre at Kasnäs.', 59.889861, 21.850583, null, null, '', null, 49, '{"established":1982,"nature":["Archipelago"],"trail":{"name":"Holma nature trail","distance":"about 2 km"},"notes":{"trail":"No official duration found."}}'::jsonb),
  ('salamajarvi', 'Salamajärvi', 'national-park', 'Keski-Pohjanmaa', 'Wide aapa mires and wild forests cover the uplands where Central Ostrobothnia meets Central Finland. It is home to the rare wild forest reindeer.', 63.273417, 24.743056, null, 62, '', null, 50, '{"established":1982,"nature":["Mire","Forest"],"trail":{"name":"Vaatimen kierros","distance":"17.4 km","duration":"5–7 h"}}'::jsonb),
  ('salla', 'Salla', 'national-park', 'Lapland', 'Finland''s newest national park protects old, rounded fells and ancient forests near the Russian border. From Iso Pyhätunturi the views reach across the border.', 66.792583, 28.922306, null, 99.83, '', null, 51, '{"established":2022,"nature":["Fell"],"trail":{"name":"Pahanojankuru trail","distance":"14.4 km","duration":"4–5 h"}}'::jsonb),
  ('seitseminen', 'Seitseminen', 'national-park', 'Pirkanmaa', 'Old-growth pine forests, mires and eskers, with pines over 400 years old in the Multiharju forest. Kovero, a restored tenant farm, shows how people lived in the backwoods.', 61.928083, 23.426639, null, 45.5, '', null, 52, '{"established":1982,"nature":["Forest"],"trail":{"name":"Torpparintaival","distance":"6.2 km","duration":"about 2 h"}}'::jsonb),
  ('selkameri', 'Selkämeri', 'national-park', 'Satakunta', 'A sea park off the Satakunta coast, almost all of it open water with only about 15 km² of land. Short island trails on Iso-Enskeri, Säppi and Kuuskajaskari offer a taste of the outer archipelago.', 61.412556, 21.355, null, null, '', null, 53, '{"established":2011,"nature":["Archipelago"],"trail":{"name":"Iso-Enskeri nature trail","distance":"3 km"},"notes":{"trail":"No official duration found."}}'::jsonb),
  ('sipoonkorpi', 'Sipoonkorpi', 'national-park', 'Uusimaa', 'Rocky hills, spruce woods and brooks on the northern edge of the Helsinki region. Despite being so close to the city, much of it still feels like deep backwoods.', 60.310667, 25.191194, null, 18.6, '', null, 54, '{"established":2011,"nature":["Forest"],"trail":{"name":"Kalkinpolttaja trail","distance":"4.9 km","duration":"2–3 h"}}'::jsonb),
  ('syote', 'Syöte', 'national-park', 'Pohjois-Pohjanmaa', 'Old spruce forests cover rounded fells, eskers and mires in Finland''s southernmost fell area. The Syöte circular trail loops over the Pytkynharju ridge.', 65.748528, 27.832333, null, 299, '', null, 55, '{"established":2000,"nature":["Forest","Fell"],"trail":{"name":"Syötteen kierros","distance":"19.3 km","duration":"4–6 h"}}'::jsonb),
  ('tammisaaren-saaristo', 'Tammisaaren saaristo', 'national-park', 'Uusimaa', 'Islands, skerries and open sea off the south coast near Raasepori. Short nature trails on Älgö, Modermagan and Jussarö make it a favourite with paddlers.', 59.857167, 23.434, null, 52, '', null, 56, '{"established":1989,"nature":["Archipelago"],"trail":{"name":"Älgö nature trail","distance":"2 km"},"notes":{"trail":"No official duration found."}}'::jsonb),
  ('teijo', 'Teijo', 'national-park', 'Varsinais-Suomi', 'Pine heaths, lakes and mires in the Salo region of Southwest Finland. Lake Matildanjärvi, ringed by a popular trail, is its best-known spot.', 60.236361, 22.979111, null, 33.85, '', null, 57, '{"established":2015,"nature":["Forest","Lake Scenery","Mire"],"trail":{"name":"Lake Matildanjärvi trail","distance":"6.1 km","duration":"2.5 h"}}'::jsonb),
  ('tiilikkajarvi', 'Tiilikkajärvi', 'national-park', 'Pohjois-Savo', 'Mires, eskers and lakes in the backwoods between North Savo and Kainuu. Venäjänhiekka, a long sandy shore on Lake Tiilikkajärvi, is its most popular spot.', 63.645222, 28.375333, null, 34, '', null, 58, '{"established":1982,"nature":["Mire","Lake Scenery"],"trail":{"name":"Uiton kierto","distance":"7.1 km","duration":"3 h"}}'::jsonb),
  ('torronsuo', 'Torronsuo', 'national-park', 'Kanta-Häme', 'One of Finland''s deepest bogs, with peat layers more than 12 metres thick. Long duckboard trails cross the open bog to viewing towers.', 60.736556, 23.632639, null, 25.5, '', null, 59, '{"established":1990,"nature":["Mire"],"trail":{"name":"Suotaival","distance":"8.6 km","duration":"2–3 h"}}'::jsonb),
  ('urho-kekkonen', 'Urho Kekkonen', 'national-park', 'Lapland', 'This vast park covers the Saariselkä fells and the wilderness to their south and east. Open wilderness huts make it a favourite for multi-day treks, with Kiilopää and Saariselkä as gateways.', 68.188778, 28.31875, null, 2550, '', null, 60, '{"established":1983,"nature":["Fell"],"trail":{"name":"Luirojärvi loop from Kiilopää","distance":"about 71 km","duration":"about 7 days"}}'::jsonb),
  ('valkmusa', 'Valkmusa', 'national-park', 'Kymenlaakso', 'Open bogs and pine mires near the Gulf of Finland coast. It is known for its rich mire butterflies, best seen in spring and summer.', 60.561139, 26.70025, null, 17, '', null, 61, '{"established":1996,"nature":["Mire"],"trail":{"name":"Valkmusa circle trail","distance":"2.5 km"},"notes":{"trail":"No official duration found."}}'::jsonb),
  ('paijanne', 'Päijänne', 'national-park', 'Päijät-Häme', 'Islands in Päijänne, Finland''s second-largest lake. Its highlight is Kelvenne, a long, narrow esker island with sandy shores.', 61.385444, 25.424833, null, 14, '', null, 62, '{"established":1993,"nature":["Lake Scenery"],"trail":{"name":"Kelvenne trail","distance":"9.7 km","duration":"2–4 h"}}'::jsonb)
